<?php
declare(strict_types=1);
namespace EPejabat\Modules\Training;
use EPejabat\Core\{Database,Core,Audit,MasterData};
final class Cpd {
 public static function rule(\PDO $p,int $u,int $programme,array $d):int {ExtendedMigrations::require($p);return Core::tx($p,function()use($p,$u,$programme,$d){$r=Policy::programme($p,$programme,true);Policy::require($p,$u,'cpd.manage',$r);$c=[];foreach(['category','official_reference'] as $k)$c[$k]=Core::text($d[$k]??'',1000);$c['regulator_id']=MasterData::validate($p,Core::id($d['regulator_id']??''),'regulator');$c['regulator']=Database::query($p,'SELECT name FROM master_data WHERE id=?',[$c['regulator_id']])->fetchColumn();$c['profession_id']=MasterData::validate($p,Core::id($d['profession_id']??''),'profession');$c['classification']=$d['classification']??'';if(!in_array($c['classification'],['NONE','GENERIC','FUNCTIONAL'],true))throw new \RuntimeException('Classification diperlukan.');foreach(['effective_from','effective_until'] as $k)$c[$k]=Workflow::date($d[$k]??'');if($c['effective_from']>$c['effective_until'])throw new \RuntimeException('Tarikh rule tidak sah.');$c['calculation']=$d['calculation']??'';if(!in_array($c['calculation'],['FIXED','PER_HOUR','PER_DAY'],true))throw new \RuntimeException('Calculation diperlukan.');$c['maximum']=Workflow::number($d['maximum']??null);if(!isset($d['allow_multi_role_sum'])||!in_array($d['allow_multi_role_sum'],[0,1,'0','1'],true))throw new \RuntimeException('Double claim policy diperlukan.');$c['allow_multi_role_sum']=(int)$d['allow_multi_role_sum'];$c['roles']=[];foreach($d['roles']??[] as $role=>$points){if(!Database::query($p,'SELECT 1 FROM training_participation_roles WHERE programme_id=? AND code=? AND is_active=1',[$programme,$role])->fetchColumn())throw new \RuntimeException('Role tidak sah.');$c['roles'][$role]=Workflow::number($points);}if(!$c['roles'])throw new \RuntimeException('Role matrix diperlukan.');$n=(int)Database::query($p,'SELECT COALESCE(MAX(version),0)+1 FROM training_cpd_rules WHERE programme_id=?',[$programme])->fetchColumn();Database::query($p,'INSERT INTO training_cpd_rules(programme_id,version,config_json,created_by) VALUES(?,?,?,?)',[$programme,$n,Workflow::json($c),$u]);$id=(int)$p->lastInsertId();Audit::record($p,'cpd.rule_created',$u,(int)$r['owner_organisation_id'],(string)$id,'training',null,null,$c);return $id;});}
 public static function verifyRule(\PDO $p,int $u,int $id):void {Core::tx($p,function()use($p,$u,$id){$rule=Database::query($p,'SELECT * FROM training_cpd_rules WHERE id=? FOR UPDATE',[$id])->fetch();if(!$rule||$rule['status']!=='DRAFT')throw new \RuntimeException('Rule bukan draft.');$r=Policy::programme($p,(int)$rule['programme_id'],true);Policy::require($p,$u,'cpd.approve',$r);Workflow::reviewer($p,$u,(int)$rule['created_by']);Database::query($p,"UPDATE training_cpd_rules SET status='VERIFIED',verified_by=?,verified_at=UTC_TIMESTAMP() WHERE id=?",[$u,$id]);Audit::record($p,'cpd.rule_verified',$u,(int)$r['owner_organisation_id'],(string)$id,'training');});}
 public static function calculate(\PDO $p,int $u,int $programme,int $registration,int $rule):int {return Core::tx($p,function()use($p,$u,$programme,$registration,$rule){$r=Policy::programme($p,$programme,true);Policy::require($p,$u,'cpd.manage',$r);$reg=Workflow::registration($p,$u,$programme,$registration,'cpd.manage');if(!Attendance::complete($p,$u,$programme,$registration))throw new \RuntimeException('Attendance belum complete.');$rr=Database::query($p,"SELECT * FROM training_cpd_rules WHERE id=? AND programme_id=? AND status='VERIFIED'",[$rule,$programme])->fetch();if(!$rr)throw new \RuntimeException('Verified rule diperlukan.');$c=json_decode($rr['config_json'],true);$pc=Policy::config($p,$r,true);$snapshot=json_decode($reg['snapshot_json'],true);if((int)$snapshot['profession_id']!==$c['profession_id']||$pc['classification']!==$c['classification']||$pc['start_at']<$c['effective_from']||$pc['end_at']>$c['effective_until'])throw new \RuntimeException('Rule tidak sepadan profession/classification/tarikh.');$roles=Database::query($p,'SELECT pr.code FROM training_participation_assignments a JOIN training_participation_roles pr ON pr.id=a.role_id WHERE a.registration_id=? AND pr.is_active=1',[$registration])->fetchAll(\PDO::FETCH_COLUMN);$days=(int)Database::query($p,'SELECT COUNT(DISTINCT DATE(start_at)) FROM training_sessions WHERE programme_id=?',[$programme])->fetchColumn();$breakdown=[];foreach($roles as $role)if(isset($c['roles'][$role]))$breakdown[$role]=$c['roles'][$role]*match($c['calculation']){'FIXED'=>1,'PER_HOUR'=>(float)$pc['effective_hours'],'PER_DAY'=>$days};if(!$breakdown)throw new \RuntimeException('Tiada role layak.');$points=min($c['maximum'],$c['allow_multi_role_sum']?array_sum($breakdown):max($breakdown));return self::record($p,$u,$r,$reg,$points,['roles'=>$breakdown,'aggregation'=>$c['allow_multi_role_sum']?'SUM':'MAX','rule'=>$c],$rule,'Verified rule calculation',$c['official_reference']);});}
 private static function evidence(\PDO $p,int $programme,int $rid):string {$r=Policy::programme($p,$programme);$events=Database::query($p,'SELECT e.id,e.action,e.checkpoint_key,e.happened_at,s.policy_json FROM training_attendance_events e JOIN training_sessions s ON s.id=e.session_id WHERE e.registration_id=? AND s.programme_id=? ORDER BY e.id',[$rid,$programme])->fetchAll();$roles=Database::query($p,'SELECT role_id FROM training_participation_assignments WHERE registration_id=? ORDER BY role_id',[$rid])->fetchAll();$sessions=Database::query($p,'SELECT id,start_at,end_at,policy_json FROM training_sessions WHERE programme_id=? ORDER BY id',[$programme])->fetchAll();return hash('sha256',Workflow::json(['published_revision'=>$r['published_revision_id'],'events'=>$events,'roles'=>$roles,'sessions'=>$sessions]));}
 private static function record(\PDO $p,int $u,array $r,array $reg,float $points,array $data,?int $rule,string $reason,string $reference):int {$data['evidence_sha256']=self::evidence($p,(int)$r['id'],(int)$reg['id']);$n=(int)Database::query($p,'SELECT COALESCE(MAX(version),0)+1 FROM training_cpd_records WHERE registration_id=?',[$reg['id']])->fetchColumn();Database::query($p,'INSERT INTO training_cpd_records(registration_id,rule_id,version,points,breakdown_json,snapshot_json,created_by,reason,reference_text) VALUES(?,?,?,?,?,?,?,?,?)',[$reg['id'],$rule,$n,$points,Workflow::json($data),$reg['snapshot_json'],$u,Core::text($reason,500),Core::text($reference,1000)]);$id=(int)$p->lastInsertId();Audit::record($p,'cpd.record_proposed',$u,(int)$r['owner_organisation_id'],(string)$id,'training',$reason,null,['points'=>$points,'reference'=>$reference]);return $id;}
 public static function override(\PDO $p,int $u,int $programme,int $registration,float $points,string $reason,string $reference):int {return Core::tx($p,function()use($p,$u,$programme,$registration,$points,$reason,$reference){$r=Policy::programme($p,$programme,true);Policy::require($p,$u,'cpd.manage',$r);$reg=Workflow::registration($p,$u,$programme,$registration,'cpd.manage');if(!Attendance::complete($p,$u,$programme,$registration))throw new \RuntimeException('Attendance belum complete.');return self::record($p,$u,$r,$reg,Workflow::number($points),['manual'=>true],null,$reason,$reference);});}
 public static function approve(\PDO $p,int $u,int $id):void {Core::tx($p,function()use($p,$u,$id){$cp=Database::query($p,'SELECT c.*,r.programme_id FROM training_cpd_records c JOIN training_registrations r ON r.id=c.registration_id WHERE c.id=? FOR UPDATE',[$id])->fetch();if(!$cp||$cp['status']!=='PENDING')throw new \RuntimeException('CPD bukan pending.');$r=Policy::programme($p,(int)$cp['programme_id'],true);Policy::require($p,$u,'cpd.approve',$r);Workflow::reviewer($p,$u,(int)$cp['created_by']);$breakdown=json_decode($cp['breakdown_json'],true);if(!hash_equals($breakdown['evidence_sha256'],self::evidence($p,(int)$r['id'],(int)$cp['registration_id'])))throw new \RuntimeException('Evidence berubah; kira/propose semula.');if(!Attendance::complete($p,$u,(int)$r['id'],(int)$cp['registration_id']))throw new \RuntimeException('Attendance tidak layak.');Database::query($p,"UPDATE training_cpd_records SET status='SUPERSEDED' WHERE registration_id=? AND status='APPROVED'",[$cp['registration_id']]);Database::query($p,"UPDATE training_cpd_records SET status='APPROVED',approved_by=? WHERE id=?",[$u,$id]);Audit::record($p,'cpd.record_approved',$u,(int)$r['owner_organisation_id'],(string)$id,'training',$cp['reason'],null,['points'=>$cp['points']]);});}
 public static function void(\PDO $p,int $u,int $id,string $reason):void {Core::tx($p,function()use($p,$u,$id,$reason){$c=Database::query($p,'SELECT c.*,r.programme_id FROM training_cpd_records c JOIN training_registrations r ON r.id=c.registration_id WHERE c.id=? FOR UPDATE',[$id])->fetch();if(!$c||$c['status']!=='APPROVED')throw new \RuntimeException('Approved record diperlukan.');$r=Policy::programme($p,(int)$c['programme_id'],true);Policy::require($p,$u,'cpd.approve',$r);$reason=Core::text($reason,500);Database::query($p,"UPDATE training_cpd_records SET status='VOID' WHERE id=?",[$id]);Audit::record($p,'cpd.record_voided',$u,(int)$r['owner_organisation_id'],(string)$id,'training',$reason,['status'=>'APPROVED'],['status'=>'VOID']);});}
 public static function history(\PDO $p,int $u,?int $programme=null):array {$a=Policy::actor($p,$u);ExtendedMigrations::require($p);if($programme){$r=Policy::programme($p,$programme);Policy::require($p,$u,'cpd.view',$r);return Database::query($p,'SELECT c.* FROM training_cpd_records c JOIN training_registrations r ON r.id=c.registration_id WHERE r.programme_id=? ORDER BY c.id DESC',[$programme])->fetchAll();}return Database::query($p,'SELECT c.*,r.programme_id FROM training_cpd_records c JOIN training_registrations r ON r.id=c.registration_id WHERE r.staff_identity_id=? ORDER BY c.id DESC',[$a['staff_identity_id']])->fetchAll();}
}
